import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.BpFM782D.js";const m=JSON.parse('{"title":"git-workflow","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/git-workflow.md","filePath":"en/skills/git-workflow.md"}'),r={name:"en/skills/git-workflow.md"};function l(d,t,s,n,c,h){return a(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="git-workflow" tabindex="-1">git-workflow <a class="header-anchor" href="#git-workflow" aria-label="Permalink to &quot;git-workflow&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>git-workflow</td></tr><tr><td>Description</td><td>Git operation best practices. Triggers when committing, creating branches/worktrees, or opening PRs. Covers zh-TW conventional commits, commit granularity, worktree isolation, and PR flow.</td></tr><tr><td>Source Directory</td><td><code>skills/git-workflow/</code></td></tr></tbody></table><hr><h1 id="git-workflow-skill" tabindex="-1">Git Workflow Skill <a class="header-anchor" href="#git-workflow-skill" aria-label="Permalink to &quot;Git Workflow Skill&quot;">​</a></h1><p>統一 git 操作的最佳實踐，涵蓋 commit 顆粒度、訊息格式、分支策略。</p><h2 id="commit-strategy" tabindex="-1">Commit Strategy <a class="header-anchor" href="#commit-strategy" aria-label="Permalink to &quot;Commit Strategy&quot;">​</a></h2><h3 id="顆粒度原則" tabindex="-1">顆粒度原則 <a class="header-anchor" href="#顆粒度原則" aria-label="Permalink to &quot;顆粒度原則&quot;">​</a></h3><p>按<strong>變更意圖</strong>分組，而非按檔案位置。同一個意圖的變更放同一個 commit， 即使涉及多個檔案。不同意圖的變更拆開，即使在同一個檔案。</p><table tabindex="0"><thead><tr><th>類型</th><th>說明</th><th>範例</th></tr></thead><tbody><tr><td><code>style</code></td><td>格式化、import 排序</td><td>ESLint auto-fix</td></tr><tr><td><code>feat</code></td><td>新功能</td><td>Hero Banner 新增</td></tr><tr><td><code>refactor</code></td><td>結構改善</td><td>提取元件</td></tr><tr><td><code>fix</code></td><td>Bug 修復</td><td>Lint errors 修復</td></tr><tr><td><code>test</code></td><td>測試新增/改善</td><td>覆蓋率提升</td></tr><tr><td><code>chore</code></td><td>工具/設定</td><td>.gitignore 更新</td></tr><tr><td><code>docs</code></td><td>文件變更</td><td>README 更新</td></tr><tr><td><code>perf</code></td><td>效能優化</td><td>Lighthouse 改善</td></tr></tbody></table><h3 id="commit-message-格式" tabindex="-1">Commit Message 格式 <a class="header-anchor" href="#commit-message-格式" aria-label="Permalink to &quot;Commit Message 格式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;type&gt;: &lt;中文描述&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;可選的詳細說明&gt;</span></span></code></pre></div><p>規則：</p><ul><li>type 用英文、描述用中文</li><li>不加 Co-Authored-By</li><li>用 HEREDOC 傳遞 message 確保格式正確</li><li>描述聚焦「為什麼」而非「做了什麼」</li></ul><h3 id="階段性-commit" tabindex="-1">階段性 Commit <a class="header-anchor" href="#階段性-commit" aria-label="Permalink to &quot;階段性 Commit&quot;">​</a></h3><p>長時間工作時，每完成一個邏輯階段就 commit，不要累積大量變更：</p><ul><li>完成一個功能模組</li><li>通過一輪品質檢查</li><li>重構告一段落</li></ul><h2 id="branch-strategy" tabindex="-1">Branch Strategy <a class="header-anchor" href="#branch-strategy" aria-label="Permalink to &quot;Branch Strategy&quot;">​</a></h2><h3 id="worktree-隔離開發" tabindex="-1">Worktree 隔離開發 <a class="header-anchor" href="#worktree-隔離開發" aria-label="Permalink to &quot;Worktree 隔離開發&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .worktrees/feature-N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/feature-N</span></span></code></pre></div><ul><li>每個 feature 用獨立 worktree</li><li>主 worktree 保持乾淨</li><li>worktree 目錄已在 .gitignore</li></ul><h3 id="pr-流程" tabindex="-1">PR 流程 <a class="header-anchor" href="#pr-流程" aria-label="Permalink to &quot;PR 流程&quot;">​</a></h3><p>建立 PR 時：</p><ol><li>分析完整 commit history（不只看最後一個 commit）</li><li><code>git diff main...HEAD</code> 看所有變更</li><li>PR title &lt; 70 字元</li><li>Body 包含 Summary + Test Plan</li><li>Push 時用 <code>-u</code> flag</li></ol><h2 id="staging-安全" tabindex="-1">Staging 安全 <a class="header-anchor" href="#staging-安全" aria-label="Permalink to &quot;Staging 安全&quot;">​</a></h2><ul><li>優先 <code>git add &amp;lt;specific files&gt;</code>，避免 <code>git add -A</code></li><li>不 commit <code>.env</code>、credentials、大型二進位檔</li><li>Stage 前確認 <code>git diff</code> 內容正確</li></ul><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><ul><li>前置 → <code>quality-gate</code> skill（確保品質通過後再 commit）</li><li>commit 後 → 可選 push + PR 建立</li></ul>`,27)])])}const p=e(r,[["render",l]]);export{m as __pageData,p as default};
